:root {
  --color-bg: #1e2d1f;
  --color-surface: #ffffff;
  --color-header-bg: #2d4a2f;
  --color-accent: #5a9e4b;
  --color-accent-light: #d4edcf;
  --color-highlight: #e8a020;
  --color-highlight-light: #fdf0d5;
  --color-text-primary: #1a2b1b;
  --color-text-secondary: #5a6e5b;
  --color-text-muted: #8fa08f;
  --color-text-white: #ffffff;
  --color-divider: #dde8dd;
  --color-dot: #c8dcc8;
  --color-dot-active: #5a9e4b;
  --color-badge-bg: #5a9e4b;
  --color-tag-bg: #eef4ee;
  --color-tag-text: #3a5e3b;
}

.trail-card {
  width: 500px;
  background: var(--color-surface);
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid var(--color-divider);
}

.trail-header {
  background: var(--color-header-bg);
  padding: 12px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.trail-badge {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: var(--color-accent-light);
}

.difficulty-tag {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.2px;
  color: var(--color-highlight);
  background: rgba(232, 160, 32, 0.15);
  padding: 3px 10px;
  border-radius: 20px;
  border: 1px solid rgba(232, 160, 32, 0.35);
}

.trail-title {
  padding: 16px 20px 12px;
  border-bottom: 1px solid var(--color-divider);
}

.trail-name {
  font-size: 22px;
  font-weight: 800;
  color: var(--color-text-primary);
  margin: 0 0 4px 0;
  line-height: 1.1;
}

.trail-region {
  font-size: 12px;
  color: var(--color-text-muted);
  margin: 0;
  font-weight: 500;
}

.trail-stats {
  display: flex;
  align-items: center;
  padding: 14px 20px;
  border-bottom: 1px solid var(--color-divider);
  background: var(--color-accent-light);
}

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 1;
}

.stat-value {
  font-size: 17px;
  font-weight: 800;
  color: var(--color-text-primary);
  line-height: 1.1;
}

.stat-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--color-text-secondary);
  letter-spacing: 0.5px;
  margin-top: 2px;
  text-transform: uppercase;
}

.stat-divider {
  width: 1px;
  height: 30px;
  background: var(--color-accent);
  opacity: 0.3;
}

.trail-body {
  display: flex;
  gap: 0;
}

.waypoints {
  flex: 1;
  padding: 14px 16px 16px 20px;
  border-right: 1px solid var(--color-divider);
}

.trail-meta {
  width: 170px;
  padding: 14px 16px 16px;
}

.section-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.2px;
  color: var(--color-text-muted);
  margin: 0 0 10px 0;
}

.waypoint-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.waypoint {
  display: flex;
  align-items: center;
  gap: 8px;
}

.wp-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-dot);
  flex-shrink: 0;
}

.wp-dot.active {
  background: var(--color-dot-active);
}

.wp-name {
  font-size: 12px;
  font-weight: 500;
  color: var(--color-text-primary);
  flex: 1;
}

.wp-dist {
  font-size: 11px;
  font-weight: 700;
  color: var(--color-text-secondary);
}

.condition-tags {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.tag {
  font-size: 11px;
  font-weight: 600;
  color: var(--color-tag-text);
  background: var(--color-tag-bg);
  padding: 4px 8px;
  border-radius: 6px;
  border: 1px solid var(--color-divider);
  text-align: center;
}

.tag.highlight {
  color: var(--color-highlight);
  background: var(--color-highlight-light);
  border-color: rgba(232, 160, 32, 0.3);
}
